UNION ALL SELECT 'PROCESSED_CARD_MONTHLY',      COUNT(*) FROM PROCESSED_CARD_MONTHLY      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
